Trabalhando com uma lista de objetos (o caso mais comum):

```
const clientes = [
  { nome: 'Ana', idade: 17 },
  { nome: 'Beto', idade: 22 },
  { nome: 'Caio', idade: 15 }
];

// O primeiro maior de idade: Beto.
clientes.find((cliente) => cliente.idade >= 18);
// devolve: { nome: 'Beto', idade: 22 }

// A posição da Ana:
clientes.findIndex((cliente) => cliente.nome === 'Ana');
// devolve: 0
```

Leia a setinha como "tal que": `(cliente) => cliente.idade >= 18` é "para cada cliente, teste se a idade dele é 18 ou mais".

Quando a condição for simples (comparar um valor exato), `includes`/`indexOf` continuam os mais curtos — mas a condição de `find` pode ser QUALQUER teste, até usar várias propriedades do objeto.

code.code:
const clientes = [
  { nome: 'Ana', idade: 17 },
  { nome: 'Beto', idade: 22 },
  { nome: 'Caio', idade: 15 }
];

const maior = clientes.find((c) => c.idade >= 18);
console.log(maior); // { nome: 'Beto', idade: 22 }

const posicao = clientes.findIndex((c) => c.nome === 'Ana');
console.log(posicao); // 0

console.log(clientes.find((c) => c.idade >= 100)); // undefined — ninguém passou

// Passo 1: conferimos que veio uma lista de verdade.
function encontrarCliente(clientes, nome) {
  if (!Array.isArray(clientes)) {
    throw new Error('clientes precisa ser uma lista');
  }

  // Passo 2: o teste da setinha compara o nome de cada cliente.
  return clientes.find((cliente) => cliente.nome === nome);
}

const lista = [
  { nome: 'Ana', idade: 17 },
  { nome: 'Beto', idade: 22 }
];

console.log(encontrarCliente(lista, 'Beto')); // { nome: 'Beto', idade: 22 }
console.log(encontrarCliente(lista, 'Zeca')); // undefined
